import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.CRbjHCyB.js";const m=JSON.parse('{"title":"LLVM Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"clice/changelog/llvm-changelog.md","filePath":"en/clice/changelog/llvm-changelog.md"}'),c={name:"clice/changelog/llvm-changelog.md"};function r(l,e,n,i,s,p){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="llvm-changelog" tabindex="-1">LLVM Changelog <a class="header-anchor" href="#llvm-changelog" aria-label="Permalink to &quot;LLVM Changelog&quot;">​</a></h1><p>Breaking changes encountered during each LLVM upgrade, with upstream commit references.</p><h2 id="llvm-21-→-22" tabindex="-1">LLVM 21 → 22 <a class="header-anchor" href="#llvm-21-→-22" aria-label="Permalink to &quot;LLVM 21 → 22&quot;">​</a></h2><h3 id="type-system" tabindex="-1">Type System <a class="header-anchor" href="#type-system" aria-label="Permalink to &quot;Type System&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Change</th><th>Commit</th><th>PR</th><th>Impact on clice</th></tr></thead><tbody><tr><td><code>NestedNameSpecifier</code> redesigned as a value type; <code>ElaboratedType</code> removed — tag/typedef/using/template-specialization types now carry the elaborated keyword and qualifier themselves. NNS kinds reduced to <code>Null</code>/<code>Global</code>/<code>Type</code>/<code>Namespace</code>/<code>MicrosoftSuper</code>; the old <code>Identifier</code> kind is now a <code>DependentNameType</code> component of kind <code>Type</code>.</td><td><code>91cdd35008e9</code></td><td><a href="https://github.com/llvm/llvm-project/pull/147835" target="_blank" rel="noreferrer">#147835</a></td><td>Rewrote NNS handling in the template resolver, semantic visitor, unifier, display and USR generation. <code>rewrite_specifier</code> collapsed to a single type-component rewrite; NNS occurrence handling dropped the <code>Identifier</code>/<code>NamespaceAlias</code> cases (dependent chains are now visited as <code>DependentNameTypeLoc</code>s).</td></tr><tr><td><code>DependentTemplateSpecializationType</code> removed; a dependent specialization is a <code>TemplateSpecializationType</code> whose <code>TemplateName</code> is a <code>DependentTemplateName</code>. <code>ASTContext::getDependentTemplateSpecializationType</code> gone; <code>getTemplateSpecializationType</code> takes an <code>ElaboratedTypeKeyword</code> first parameter.</td><td><code>ba9d1c41c41d</code></td><td><a href="https://github.com/llvm/llvm-project/pull/158109" target="_blank" rel="noreferrer">#158109</a></td><td>Resolver&#39;s DTST lookup/rewrite/pseudo-SFINAE paths merged into the TST paths, keyed on <code>getAsDependentTemplateName()</code>.</td></tr><tr><td><code>InjectedClassNameType</code> is now a <code>TagType</code> subclass and no longer stores the injected specialization; use <code>CXXRecordDecl::getCanonicalTemplateSpecializationType(Ctx)</code>. <code>TagDecl::getTypeForDecl</code> deleted; use <code>ASTContext::getCanonicalTagType</code>.</td><td><code>91cdd35008e9</code></td><td><a href="https://github.com/llvm/llvm-project/pull/147835" target="_blank" rel="noreferrer">#147835</a></td><td>Resolver, unifier, USR generation and hover layout info migrated to the canonical accessors.</td></tr><tr><td><code>NamespaceBaseDecl</code> introduced; a <code>Namespace</code> NNS component stores it (covers both namespaces and namespace aliases).</td><td><code>4a9eaad9e128</code></td><td><a href="https://github.com/llvm/llvm-project/pull/149123" target="_blank" rel="noreferrer">#149123</a></td><td>Namespace lookup goes through <code>getAsNamespaceAndPrefix().Namespace-&gt;getNamespace()</code>; alias occurrences reference the base decl directly.</td></tr><tr><td><code>UsingType::getFoundDecl</code>/<code>getUnderlyingType</code> renamed to <code>getDecl</code>/<code>desugar</code>; <code>TypedefTypeLoc::getTypedefNameDecl</code> is <code>getDecl</code>.</td><td><code>91cdd35008e9</code></td><td><a href="https://github.com/llvm/llvm-project/pull/147835" target="_blank" rel="noreferrer">#147835</a></td><td>Mechanical renames in unifier, resolver and semantic visitor.</td></tr><tr><td>Implicit variable template specializations no longer store written template arguments.</td><td><code>1cb47c19f8ec</code></td><td><a href="https://github.com/llvm/llvm-project/pull/156329" target="_blank" rel="noreferrer">#156329</a></td><td><code>display::template_args</code> falls back to the converted argument list, so hover titles print <code>baz&lt;ns::X&lt;int&gt;&gt;</code> (converted, qualified) instead of the as-written form.</td></tr><tr><td><code>RecursiveASTVisitor</code> type traversals take a <code>TraverseQualifier</code> flag; <code>DynTypedNode::getSourceRange</code> takes <code>IncludeQualifier</code> (default excludes the qualifier of qualified type locs).</td><td><code>91cdd35008e9</code></td><td><a href="https://github.com/llvm/llvm-project/pull/147835" target="_blank" rel="noreferrer">#147835</a></td><td>Semantic visitor overrides updated; selection-tree node ranges now exclude qualifiers (matching clangd), so a cursor on a dependent name selects its <code>DependentNameTypeLoc</code> name token.</td></tr></tbody></table><h3 id="driver-frontend" tabindex="-1">Driver / Frontend <a class="header-anchor" href="#driver-frontend" aria-label="Permalink to &quot;Driver / Frontend&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Change</th><th>Commit</th><th>PR</th><th>Impact on clice</th></tr></thead><tbody><tr><td>Option handling split out of clangDriver into a clangOptions library: <code>clang/Driver/Options.inc</code> → <code>clang/Options/Options.inc</code>, <code>GetResourcesPath</code> → <code>clang/Options/OptionUtils.h</code> (namespace <code>clang</code>).</td><td><code>f63d33da0a51</code></td><td><a href="https://github.com/llvm/llvm-project/pull/167374" target="_blank" rel="noreferrer">#167374</a></td><td>Include-path and call-site updates in the argument parser.</td></tr><tr><td><code>OptTable</code> gained subcommand support: the <code>OPTION</code> record has a trailing <code>SUBCOMMANDIDS_OFFSET</code> column.</td><td><code>fdbd17d1fb0d</code></td><td><a href="https://github.com/llvm/llvm-project/pull/155026" target="_blank" rel="noreferrer">#155026</a></td><td>The <code>OPTION</code> macros expanding <code>Options.inc</code> take the extra parameter.</td></tr><tr><td><code>clang::createInvocation</code> moved to <code>clang/Driver/CreateInvocationFromArgs.h</code>.</td><td><code>d090311aa7df</code></td><td><a href="https://github.com/llvm/llvm-project/pull/169599" target="_blank" rel="noreferrer">#169599</a></td><td>Include updates in compilation and scan.</td></tr><tr><td><code>CompilerInstance</code> owns its VFS explicitly: seed it with <code>setVirtualFileSystem</code>/<code>createVirtualFileSystem</code> (the latter subsumes <code>createVFSFromCompilerInvocation</code>), then <code>createDiagnostics(Client, ShouldOwnClient)</code> and <code>createFileManager()</code> take no VFS.</td><td><code>30633f308941</code></td><td><a href="https://github.com/llvm/llvm-project/pull/158381" target="_blank" rel="noreferrer">#158381</a></td><td>Compilation and scan set the VFS on the instance before creating diagnostics and the file manager.</td></tr></tbody></table><h3 id="other" tabindex="-1">Other <a class="header-anchor" href="#other" aria-label="Permalink to &quot;Other&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Change</th><th>Commit</th><th>PR</th><th>Impact on clice</th></tr></thead><tbody><tr><td><code>llvm::sys::fs::make_absolute(current_directory, path)</code> moved to <code>llvm::sys::path::make_absolute</code>.</td><td><code>f122484b998d</code></td><td><a href="https://github.com/llvm/llvm-project/pull/161459" target="_blank" rel="noreferrer">#161459</a></td><td>Call-site update in header search config.</td></tr><tr><td><code>size_t</code> and friends are named sugar types (<code>__size_t</code>), so e.g. <code>operator new</code>&#39;s parameter prints as <code>__size_t</code> with an <code>aka unsigned long</code>.</td><td><code>7c402b8b81d2</code></td><td><a href="https://github.com/llvm/llvm-project/pull/149613" target="_blank" rel="noreferrer">#149613</a></td><td>Hover snapshots updated.</td></tr><tr><td>Anonymous tag types print as <code>(unnamed enum)</code>/<code>(unnamed struct)</code> uniformly.</td><td><code>4ef641916408</code></td><td><a href="https://github.com/llvm/llvm-project/pull/169445" target="_blank" rel="noreferrer">#169445</a></td><td>Hover snapshots updated.</td></tr><tr><td><code>PrintingPolicy::SuppressScope</code> now also drops written qualifiers of template names, and canonical tag types print fully qualified.</td><td><code>91cdd35008e9</code></td><td><a href="https://github.com/llvm/llvm-project/pull/147835" target="_blank" rel="noreferrer">#147835</a></td><td>Inlay type hints lose nested-class scopes (<code>Nested&lt;int&gt;</code> instead of <code>S2::Nested&lt;int&gt;</code>, matching clangd); hover of <code>this</code> prints the namespace-qualified class type.</td></tr></tbody></table>',9)])])}const g=t(c,[["render",r]]);export{m as __pageData,g as default};
